// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes32 signingGroupPubkeyX, bytes32 signingGroupPubkeyY) public {
        bool approved = c.approvedToLog(caller);
        vm.prank(caller);
        bool result = c.logRegisteredPubkey(signingGroupPubkeyX, signingGroupPubkeyY);
        assertTrue(result == approved);
    }
}

